package com.healthcompanion.api; import com.healthcompanion.ai.MedicalKnowledgeIngestionService; import jakarta.validation.constraints.NotBlank; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/knowledge") public class AdminKnowledgeController {private final MedicalKnowledgeIngestionService ingestion;public AdminKnowledgeController(MedicalKnowledgeIngestionService i){ingestion=i;}@PostMapping public Result ingest(@RequestBody Request r){return new Result(ingestion.ingest(r.source(),r.topic(),r.language(),r.version(),r.content()));}public record Request(@NotBlank String source,@NotBlank String topic,@NotBlank String language,@NotBlank String version,@NotBlank String content){}public record Result(int chunksCreated){} }
